// Embedded IP-to-country and IP-to-origin-ASN lookup for the
// GeoMatchStatement and AsnMatchStatement evaluations. The blob is a
// derived asset generated by internal/tools/wafgeogen from openly
// published RIR delegated-extended statistics and a RouteViews MRT RIB
// dump; the generator is the regeneration procedure, the raw inputs
// are never committed.
package inspection

import (
	"embed"
	"encoding/binary"
	"net/netip"
	"sync"
)

//go:embed geoasn_data.bin
var geoasnBlob embed.FS

var (
	blobMagic = [8]byte{'W', 'G', 'E', 'O', 'A', 'S', 'N', '1'}
)

// geoTables holds the decoded interval tables; intervals are sorted by
// start address and disjoint, so lookup is a binary search.
type geoTables struct {
	countries []string
	country   geoTable
	asn       geoTable
}

type geoTable struct {
	starts [][16]byte
	bits   []int
	values []uint32
}

var geoOnce sync.Once
var geoLoaded *geoTables
var geoErr error

func loadGeoTables() (*geoTables, error) {
	geoOnce.Do(func() {
		raw, err := geoasnBlob.ReadFile("geoasn_data.bin")
		if err != nil {
			geoErr = err
			return
		}
		geoLoaded, geoErr = decodeGeoBlob(raw)
	})
	return geoLoaded, geoErr
}

// decodeGeoBlob parses the generator's blob layout:
// magic(8), date(4), country count(4) + 2-byte codes, country table
// length(4) + bytes, asn table length(4) + bytes. Interval tables are
// a uvarint count then per-interval uvarint records of start-delta hi,
// start-delta lo, bits and value.
func decodeGeoBlob(raw []byte) (*geoTables, error) {
	if len(raw) < 20 || string(raw[:8]) != string(blobMagic[:]) {
		return nil, errGeoBlob("bad magic")
	}
	pos := 8
	date := binary.BigEndian.Uint32(raw[pos:])
	pos += 4
	if date == 0 {
		return nil, errGeoBlob("missing generation date")
	}
	ccCount := int(binary.BigEndian.Uint32(raw[pos:]))
	pos += 4
	if len(raw) < pos+2*ccCount+8 {
		return nil, errGeoBlob("truncated country codes")
	}
	countries := make([]string, ccCount)
	for i := range countries {
		countries[i] = string(raw[pos : pos+2])
		pos += 2
	}
	countryLen := int(binary.BigEndian.Uint32(raw[pos:]))
	pos += 4
	if len(raw) < pos+countryLen+4 {
		return nil, errGeoBlob("truncated country table")
	}
	countryTable, err := decodeGeoTable(raw[pos : pos+countryLen])
	if err != nil {
		return nil, err
	}
	pos += countryLen
	asnLen := int(binary.BigEndian.Uint32(raw[pos:]))
	pos += 4
	if len(raw) < pos+asnLen {
		return nil, errGeoBlob("truncated asn table")
	}
	asnTable, err := decodeGeoTable(raw[pos : pos+asnLen])
	if err != nil {
		return nil, err
	}
	return &geoTables{countries: countries, country: countryTable, asn: asnTable}, nil
}

type errGeoBlob string

func (e errGeoBlob) Error() string { return "geoasn blob: " + string(e) }

func decodeGeoTable(raw []byte) (geoTable, error) {
	var table geoTable
	pos := 0
	count, read := binary.Uvarint(raw[pos:])
	if read <= 0 {
		return table, errGeoBlob("bad interval count")
	}
	pos += read
	table.starts = make([][16]byte, 0, count)
	table.bits = make([]int, 0, count)
	table.values = make([]uint32, 0, count)
	var prevEnd [16]byte
	for i := uint64(0); i < count; i++ {
		hi, n1 := binary.Uvarint(raw[pos:])
		if n1 <= 0 {
			return table, errGeoBlob("bad start delta")
		}
		pos += n1
		lo, n2 := binary.Uvarint(raw[pos:])
		if n2 <= 0 {
			return table, errGeoBlob("bad start delta")
		}
		pos += n2
		bits, n3 := binary.Uvarint(raw[pos:])
		if n3 <= 0 || bits > 128 {
			return table, errGeoBlob("bad interval bits")
		}
		pos += n3
		value, n4 := binary.Uvarint(raw[pos:])
		if n4 <= 0 {
			return table, errGeoBlob("bad interval value")
		}
		pos += n4
		start := add128(prevEnd, hi, lo)
		table.starts = append(table.starts, start)
		table.bits = append(table.bits, int(bits))
		table.values = append(table.values, uint32(value))
		prevEnd = addPow2(start, int(bits))
	}
	return table, nil
}

// add128 adds a 128-bit value given as hi/lo halves to a 16-byte
// big-endian address.
func add128(base [16]byte, hi, lo uint64) [16]byte {
	out := base
	carry := uint64(0)
	for i := 15; i >= 0; i-- {
		var add uint64
		if i >= 8 {
			add = (hi >> (8 * uint(i-8))) & 0xff
		} else {
			add = (lo >> (8 * uint(i))) & 0xff
		}
		v := uint64(out[i]) + add + carry
		out[i] = byte(v)
		carry = v >> 8
	}
	return out
}

// addPow2 returns start plus 2^bits addresses.
func addPow2(start [16]byte, bits int) [16]byte {
	out := start
	i := 15 - bits/8
	add := byte(1 << (bits % 8))
	for ; i >= 0; i-- {
		v := int(out[i]) + int(add)
		out[i] = byte(v)
		if v <= 255 {
			break
		}
		add = 1
	}
	return out
}

// geoLookup returns the table value covering the address. An interval
// is aligned to its size, so containment is the equality of the
// leading 128-bits address bits with the interval start.
func (t *geoTable) geoLookup(addr [16]byte) (uint32, bool) {
	lo, hi := 0, len(t.starts)-1
	for lo < hi {
		mid := (lo + hi + 1) / 2
		if addrLessOrEqual(t.starts[mid], addr) {
			lo = mid
		} else {
			hi = mid - 1
		}
	}
	if lo < 0 {
		return 0, false
	}
	start := t.starts[lo]
	if !addrLessOrEqual(start, addr) {
		return 0, false
	}
	bits := t.bits[lo]
	if bits == 0 {
		return t.values[lo], true
	}
	// Compare the leading 128-bits bits of addr with start.
	shiftBits := 128 - bits
	fullBytes := shiftBits / 8
	rem := shiftBits % 8
	for i := 0; i < fullBytes; i++ {
		if addr[i] != start[i] {
			return 0, false
		}
	}
	if rem > 0 {
		mask := byte(0xff) << (8 - rem)
		if addr[fullBytes]&mask != start[fullBytes]&mask {
			return 0, false
		}
	}
	return t.values[lo], true
}

func addrLessOrEqual(a, b [16]byte) bool {
	for i := 0; i < 16; i++ {
		if a[i] != b[i] {
			return a[i] < b[i]
		}
	}
	return true
}

// addr16 maps an address into the 128-bit space the tables use.
func addr16(addr netip.Addr) ([16]byte, bool) {
	addr = addr.Unmap()
	if !addr.IsValid() {
		return [16]byte{}, false
	}
	if addr.Is4() {
		b4 := addr.As4()
		var raw [16]byte
		copy(raw[12:], b4[:])
		return raw, true
	}
	return addr.As16(), true
}

// CountryForIP resolves the registry-delegated country code of the
// address. The boolean reports whether any allocation covers it.
func CountryForIP(addr netip.Addr) (string, bool) {
	tables, err := loadGeoTables()
	if err != nil {
		return "", false
	}
	raw, ok := addr16(addr)
	if !ok {
		return "", false
	}
	idx, found := tables.country.geoLookup(raw)
	if !found || idx == 0 || int(idx) > len(tables.countries) {
		return "", false
	}
	return tables.countries[idx-1], true
}

// ASNForIP resolves the origin ASN of the address from the embedded
// routing-table snapshot.
func ASNForIP(addr netip.Addr) (uint32, bool) {
	tables, err := loadGeoTables()
	if err != nil {
		return 0, false
	}
	raw, ok := addr16(addr)
	if !ok {
		return 0, false
	}
	return tables.asn.geoLookup(raw)
}
